pub fn dispatch_option(
    repo: &mut impl crate::kernel::Repository<Query>, id: &str, args: OptionArgs, mutations: &mut Vec<crate::kernel::MutationRecord>, owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>, command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
) -> crate::kernel::DispatchResult<Query> {
        args.option.check_invariants()?;
        args.key.check_invariants()?;
        if let Some(v) = &args.value { v.check_invariants()?; }
        if let Some(v) = &args.at { v.check_invariants()?; }
    let with_references = crate::kernel::WithReferences { command_deref: &command_deref, args: &args, owner_deref: &owner_deref };
    let seed_projections = crate::kernel::seeded_projections(&with_references, QUERY_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "Option",
        "Bluebook::Query",
        "Query",
        "owner_id, name.value",
        &with_references,
        &[
            crate::kernel::GivenSpec { description: "an option is named", expr: Expr::Not(Box::new(Expr::Empty(Box::new(Expr::ToS(Box::new(Expr::Lookup("option.value"))))))), corrects_event: None },
        ],
        None,
        |record| {
        record.options.push(AskOption { option: args.option.value.clone(), key: args.key.value.clone(), value: args.value.clone().map(|v| v.value.clone()), at: args.at.clone().map(|v| v.value.clone()) });
            Ok(())
        },
        &[

        ],
        &query_invariants(),
        &["OptionAttached"],
        args.to_json(),
        mutations,
        seed_projections,
    )
}

